  function svg(name, size = 32, opts = {}) {
    const o = typeof opts === 'string' ? { cls: opts } : opts;
    const cls = o.cls || '';
    const style = [o.fill && `--ic-fill:${o.fill}`, o.line && `--ic-line:${o.line}`].filter(Boolean).join(';');
    const head = `<svg class="px px-${name} ${cls}" width="${size}" height="${size}" viewBox="0 0 24 24" shape-rendering="crispEdges" aria-hidden="true" focusable="false"${style ? ` style="${style}"` : ''}>`;
    if (OWN[name]) return `${head}${OWN[name]}</svg>`;
    if (BRAND[name]) return `${head}<path class="f" d="${TILE_BODY}"/><path class="g" d="${BRAND[name]}"/><path class="l" fill-rule="evenodd" d="${TILE_LINE}"/></svg>`;
    const icon = LIB[MAP[name]];
    if (!icon) return '';
    const fill = o.mono ? '' : `<g class="f">${icon[1]}</g>`;
    return `${head}${fill}<g class="l">${icon[0]}</g></svg>`;
  }

